import React from 'react';
import { useOutletContext, Outlet } from 'react-router-dom';
import ProjectNavbar from '../../components/ProjectNavbar';
import './ATSModule.css';

const ATSModule = () => {
  const context = useOutletContext(); // This brings in the global state from MainLayout

  return (
    <div className="ats-wrapper">
      <ProjectNavbar basePath="ats" links={["Async", "Skill", "Similarity", "DB"]} />
      
      {/* The Outlet renders the child route (ATS_P1, ATS_P2, etc.) */}
      {/* We pass the context down so children have access to the data */}
      <div className="ats-content-area">
        <Outlet context={context} />
      </div>
    </div>
  );
};

export default ATSModule;
